const { app, BrowserWindow, ipcMain } = require('electron');
const path = require('path');
const os = require('os');

function createWindow() {
  const win = new BrowserWindow({
    width: 900,
    height: 600,
    frame: false,             // Frameless window: eliminates standard OS titlebar
    transparent: true,         // Allows custom non-rectangular floating UI
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true,  // Enforces secure sandbox boundary
      nodeIntegration: false   // Prevents malicious code execution
    }
  });

  win.loadFile('index.html');
}

// Handle asynchronous IPC invoke from Renderer
ipcMain.handle('system:get-telemetry', async () => {
  return {
    cpus: os.cpus().length,
    freeMemMB: Math.round(os.freemem() / 1024 / 1024),
    uptimeSeconds: os.uptime()
  };
});

app.whenReady().then(createWindow);

const { contextBridge, ipcRenderer } = require('electron');

// Expose safe, selected functions to the window object in Renderer
contextBridge.exposeInMainWorld('electronAPI', {
  getSystemTelemetry: () => ipcRenderer.invoke('system:get-telemetry'),
  closeApp: () => ipcRenderer.send('window:close')
});

